    Renderer* m_pRenderer;
    int CompleteConnect(void* pReceivePin)
    {
        int hr = m_pRenderer->CompleteConnect(pReceivePin);
        if (hr < 0) return hr;
        return BasePin::CompleteConnect(pReceivePin);
    }
};
int main()
{
